import loggingimport sysimport timefrom pathlib import Pathfrom typing import Optional, Tupleimport numpy as npimport pandas as pd# Importa funzioni di validazione e calcolosys.path.insert(0, str(Path(__file__).parent.parent / "mobile"))from data_validator import (DataValidationError, calculate_bearing,                            calculate_mean_direction, calculate_mean_distance,                            haversine_distance, validate_csv_file,                            validate_data, validate_geographic_coordinates)# Configura logginglogger = logging.getLogger(__name__)# Costanti per Campi FlegreiLAT_CENTRO = 40.8062LON_CENTRO = 14.1410# Default timeout per operazioni lunghe (in minuti)DEFAULT_OPERATION_TIMEOUT = 30def load_data(catalogo_path: str = "catalogo_terremoti_unici.csv") -> pd.DataFrame:    """Carica e valida il catalogo eventi."""    logger.info("📖 Caricamento del catalogo eventi...")    # Validate file exists and is readable    catalogo_path = Path(catalogo_path)    if not catalogo_path.exists():        raise FileNotFoundError(f"File catalogo non trovato: {catalogo_path}")    if catalogo_path.stat().st_size == 0:        raise DataValidationError(            "File catalogo e' vuoto", errors=["Catalog file is empty"]        )    # Load and validate CSV    try:        df = validate_csv_file(            catalogo_path,            required_columns={                "event_id",                "Tempo_Riferimento_ISO",                "Numero_Stazioni_Attivate",            },        )    except DataValidationError as e:        logger.error(f"❌ Validazione catalogo fallita: {e.message}")        for err in e.errors:            logger.error(f"   {err}")        raise    # Convert datetime and sort    df["Tempo"] = pd.to_datetime(df["Tempo_Riferimento_ISO"])    df.set_index("Tempo", inplace=True)    df.sort_index(inplace=True)    # Check for empty DataFrame    if len(df) == 0:        raise DataValidationError(            "Catalogo eventi e' vuoto", errors=["No events found in catalog"]        )    # Check for valid date range    if df.index.min() > df.index.max():        raise DataValidationError(            "Date nel catalogo non valide", errors=["Invalid date range"]        )    logger.info(        f"✅ Caricati {len(df)} eventi unici (da {df.index.min()} a {df.index.max()})"    )    return dfdef add_temporal_features(df: pd.DataFrame) -> pd.DataFrame:    """Aggiunge feature temporali avanzate."""    logger.info("⚙️ Aggiunta feature temporali...")    # Check if DataFrame is empty    if len(df) == 0:        logger.warning("DataFrame vuoto, feature temporali saltate")        return df    # 1. Resampling: Raggruppamento per ora    df_orario = (        df.resample("1h")        .agg(            numero_eventi=("event_id", "count"),            energia_max=("Numero_Stazioni_Attivate", "max"),            energia_media=("Numero_Stazioni_Attivate", "mean"),            energia_std=("Numero_Stazioni_Attivate", "std"),            energia_min=("Numero_Stazioni_Attivate", "min"),        )        .fillna(0)    )    # Check if resampled DataFrame is empty    if len(df_orario) == 0:        raise DataValidationError("Resampling temporale ha prodotto DataFrame vuoto")    # 2. Rolling features (finestre temporali)    for window in [6, 12, 24, 48]:        df_orario[f"eventi_ultime_{window}h"] = (            df_orario["numero_eventi"].rolling(window=window).sum()        )        df_orario[f"energia_max_ultime_{window}h"] = (            df_orario["energia_max"].rolling(window=window).max()        )        df_orario[f"energia_media_ultime_{window}h"] = (            df_orario["energia_media"].rolling(window=window).mean()        )        df_orario[f"energia_std_ultime_{window}h"] = (            df_orario["energia_std"].rolling(window=window).mean()        )    # 3. Trend features (pendenza regressione lineare)    for window in [12, 24]:        df_orario[f"trend_eventi_{window}h"] = (            df_orario["numero_eventi"]            .rolling(window=window)            .apply(                lambda x: np.polyfit(np.arange(len(x)), x, 1)[0] if len(x) > 1 else 0,                raw=False,            )        )        df_orario[f"trend_energia_{window}h"] = (            df_orario["energia_max"]            .rolling(window=window)            .apply(                lambda x: np.polyfit(np.arange(len(x)), x, 1)[0] if len(x) > 1 else 0,                raw=False,            )        )    # 4. Varianza    df_orario["varianza_eventi_24h"] = df_orario["numero_eventi"].rolling(24).var()    df_orario["varianza_energia_24h"] = df_orario["energia_max"].rolling(24).var()    # 5. Feature temporali aggiuntive    df_orario["ora_del_giorno"] = df_orario.index.hour    df_orario["giorno_della_settimana"] = df_orario.index.dayofweek    df_orario["is_notte"] = df_orario.index.hour.isin(        [0, 1, 2, 3, 4, 5, 22, 23]    ).astype(int)    df_orario["is_weekend"] = df_orario.index.dayofweek.isin([5, 6]).astype(int)    # 6. Rate di cambiamento    df_orario["event_rate_1h"] = df_orario["numero_eventi"].diff()    df_orario["event_rate_6h"] = df_orario["numero_eventi"].diff(6)    df_orario["energia_rate_1h"] = df_orario["energia_max"].diff()    return df_orariodef add_future_target(    df_orario: pd.DataFrame, target_window: int = 24, threshold: int = 18) -> pd.DataFrame:    """Aggiunge la variabile target: evento con >=threshold stazioni nelle prossime N ore."""    logger.info(        f"🎯 Generazione target (finestra {target_window}h, soglia {threshold} stazioni)..."    )    # Check if DataFrame is empty    if len(df_orario) == 0:        raise DataValidationError("DataFrame vuoto, impossibile generare target")    # Calcola il massimo numero di stazioni nelle prossime N ore    df_orario["max_energia_futura"] = (        df_orario["energia_max"]        .rolling(window=target_window, min_periods=1)        .max()        .shift(-target_window)    )    # Target: 1 se ci sara un evento con >=threshold stazioni nelle prossime N ore    df_orario["Target_Allarme"] = (df_orario["max_energia_futura"] >= threshold).astype(        int    )    # Conta quanti eventi futuri superano la soglia    df_orario["future_events_above_threshold"] = (        df_orario["energia_max"]        .rolling(window=target_window, min_periods=1)        .apply(lambda x: (x >= threshold).sum())        .shift(-target_window)        .fillna(0)    )    # Check if target generation was successful    if df_orario["Target_Allarme"].isna().all():        logger.warning("Tutti i target sono NaN, verifica finestra temporale")    logger.info(        f"📊 Target generato: {df_orario['Target_Allarme'].sum()} allarmi su {len(df_orario)} ore"    )    return df_orariodef add_spatial_features(    df_orario: pd.DataFrame,    df_events: pd.DataFrame,    stations: pd.DataFrame,    center_lat: float = LAT_CENTRO,    center_lon: float = LON_CENTRO,) -> pd.DataFrame:    """Aggiunge feature spaziali al dataset orario."""    logger.info("🗺️ Aggiunta feature spaziali...")    # 1. Carica dati geospaziali    try:        geo_path = Path("output_eventi_georeferenziati.csv.gz")        if not geo_path.exists():            logger.warning(f"File {geo_path} non trovato, feature spaziali saltate")            return df_orario        df_geo = pd.read_csv(geo_path)        df_geo["arrival_iso"] = pd.to_datetime(df_geo["arrival_iso"])        # Validate geographic data        if "latitude" in df_geo.columns and "longitude" in df_geo.columns:            validate_geographic_coordinates(df_geo, "latitude", "longitude")    except FileNotFoundError:        logger.warning(            "File output_eventi_georeferenziati.csv.gz non trovato, feature spaziali saltate"        )        return df_orario    except DataValidationError as e:        logger.warning(f"Validazione dati geospaziali fallita: {e.message}")        return df_orario    except Exception as e:        logger.warning(f"Errore caricamento dati geospaziali: {e}")        return df_orario    # 2. Calcola feature spaziali per ogni ora    df_geo["ora"] = df_geo["arrival_iso"].dt.floor("1h")    # Aggrega per ora    spatial_by_hour = df_geo.groupby("ora").agg(        num_stations=("station", "nunique"),        mean_latitude=("latitude", "mean"),        mean_longitude=("longitude", "mean"),        std_latitude=("latitude", "std"),        std_longitude=("longitude", "std"),        mean_delta=("delta_seconds", "mean"),        std_delta=("delta_seconds", "std"),    )    # Merge con df_orario    df_orario = df_orario.join(spatial_by_hour, how="left").fillna(0)    # 3. Calcola distanza e direzione dal centro    df_orario["distanza_da_centro_km"] = df_orario.apply(        lambda row: (            haversine_distance(                LON_CENTRO, LAT_CENTRO, row["mean_longitude"], row["mean_latitude"]            )            if pd.notna(row["mean_longitude"])            else 0.0        ),        axis=1,    )    df_orario["direzione_da_centro_deg"] = df_orario.apply(        lambda row: (            calculate_mean_direction(                df_geo[df_geo["ora"] == row.name], LON_CENTRO, LAT_CENTRO            )            if row.name in df_geo["ora"].values            else 0.0        ),        axis=1,    )    # 4. Dispersione spaziale    df_orario["dispersione_spaziale_km"] = df_orario["std_latitude"] * 111.32    return df_orariodef add_seismological_features(    df_orario: pd.DataFrame, bvalue_window: int = 24) -> pd.DataFrame:    """Aggiunge feature sismologiche (b-value, ecc.)."""    logger.info("🌋 Aggiunta feature sismologiche...")    try:        catalogo_path = Path("catalogo_terremoti_unici.csv")        if not catalogo_path.exists():            logger.warning(                f"File {catalogo_path} non trovato, feature sismologiche saltate"            )            return df_orario        df_catalogo = pd.read_csv(catalogo_path)        df_catalogo["Tempo_Riferimento_ISO"] = pd.to_datetime(            df_catalogo["Tempo_Riferimento_ISO"]        )        df_catalogo["ora"] = df_catalogo["Tempo_Riferimento_ISO"].dt.floor("1h")        bvalue_by_hour = df_catalogo.groupby("ora").agg(            bvalue_approx=("Numero_Stazioni_Attivate", "mean"),            event_count=("event_id", "count"),        )        df_orario = df_orario.join(bvalue_by_hour, how="left").fillna(0)        # Rolling b-value        df_orario["bvalue_rolling_24h"] = (            df_orario["bvalue_approx"].rolling(window=bvalue_window).mean()        )        df_orario["bvalue_std_24h"] = (            df_orario["bvalue_approx"].rolling(window=bvalue_window).std()        )        df_orario["bvalue_change"] = df_orario["bvalue_approx"].diff()    except FileNotFoundError:        logger.warning(            "File catalogo_terremoti_unici.csv non trovato, feature sismologiche saltate"        )    except Exception as e:        logger.warning(f"Errore calcolo feature sismologiche: {e}")    return df_orariodef add_statistical_features(df_orario: pd.DataFrame) -> pd.DataFrame:    """Aggiunge feature statistiche avanzate."""    logger.info("📊 Aggiunta feature statistiche...")    # Check if DataFrame is empty    if len(df_orario) == 0:        logger.warning("DataFrame vuoto, feature statistiche saltate")        return df_orario    # 1. Percentili    for percentile in [25, 50, 75, 90, 95]:        df_orario[f"energia_p{percentile}_24h"] = (            df_orario["energia_max"].rolling(24).quantile(percentile / 100)        )    # 2. Skewness e Kurtosis    df_orario["skewness_eventi_24h"] = (        df_orario["numero_eventi"]        .rolling(24, min_periods=1)        .apply(lambda x: pd.Series(x).skew(), raw=True)    )    df_orario["kurtosis_eventi_24h"] = (        df_orario["numero_eventi"]        .rolling(24, min_periods=1)        .apply(lambda x: pd.Series(x).kurtosis(), raw=True)    )    # 3. Entropia    df_orario["entropy_24h"] = (        df_orario["numero_eventi"]        .rolling(24)        .apply(            lambda x: (                -np.sum((x / x.sum()) * np.log2(x / x.sum() + 1e-10))                if x.sum() > 0                else 0            ),            raw=False,        )    )    # 4. Autocorrelazione    df_orario["autocorr_1h"] = df_orario["numero_eventi"].autocorr(1)    df_orario["autocorr_6h"] = df_orario["numero_eventi"].autocorr(6)    return df_orariodef remove_missing_rows(    df: pd.DataFrame, max_missing_pct: float = 50.0) -> pd.DataFrame:    """    Rimuove righe con troppi valori mancanti.    Args:        df: DataFrame da pulire        max_missing_pct: Percentuale massima di valori mancanti accettata (default: 50%)    Returns:        DataFrame pulito    """    if len(df) == 0:        return df    nan_counts = df.isnull().sum(axis=1)    max_missing = int(len(df.columns) * (max_missing_pct / 100))    if max_missing <= 0:        max_missing = 1    df_clean = df[nan_counts <= max_missing].copy()    removed = len(df) - len(df_clean)    if removed > 0:        removed_pct = (removed / len(df)) * 100        logger.info(            f"🧹 Rimosse {removed} righe ({removed_pct:.1f}%) con troppi valori mancanti"        )        # Warn if too many rows removed        if removed_pct > 80:            logger.warning(                f"Attenzione: Più dell'80% delle righe rimosse ({removed_pct:.1f}%)"            )    return df_cleandef main():    """Esecuzione principale del feature engineering."""    print("🚀 Avvio Feature Engineering Avanzato per Machine Learning...")    tempo_inizio = time.time()    try:        # Setup logging        sys.path.insert(0, str(Path(__file__).parent.parent / "mobile"))        from logging_config import setup_logging        setup_logging()        # 1. Caricamento dati        df = load_data()        # 2. Aggiunta feature temporali        df_orario = add_temporal_features(df)        # 3. Aggiunta target futuro        df_orario = add_future_target(df_orario, target_window=24, threshold=18)        # 4. Aggiunta feature spaziali        try:            stations = pd.read_csv("stations.csv")            # Validate stations data            if len(stations) == 0:                logger.warning("File stations.csv vuoto, feature spaziali saltate")            elif "latitude" in stations.columns and "longitude" in stations.columns:                validate_geographic_coordinates(stations, "latitude", "longitude")                df_orario = add_spatial_features(df_orario, df, stations)            else:                logger.warning(                    "File stations.csv senza colonne coordinate, feature spaziali saltate"                )        except FileNotFoundError:            logger.warning("File stations.csv non trovato, feature spaziali saltate")        except DataValidationError as e:            logger.warning(f"Validazione stations.csv fallita: {e.message}")        except Exception as e:            logger.warning(f"Errore feature spaziali: {e}")        # 5. Aggiunta feature sismologiche        df_orario = add_seismological_features(df_orario)        # 6. Aggiunta feature statistiche        df_orario = add_statistical_features(df_orario)        # 7. Rimuovi righe con NaN        df_ml = remove_missing_rows(df_orario)        # Check if final DataFrame is valid        if len(df_ml) == 0:            raise DataValidationError(                "Dataset finale vuoto dopo feature engineering",                errors=["Final dataset is empty after feature engineering"],            )        # Check for too many missing values in final dataset        missing_pct = (            df_ml.isnull().sum().sum() / (len(df_ml) * len(df_ml.columns))        ) * 100        if missing_pct > 50:            logger.warning(f"Dataset finale ha {missing_pct:.1f}% valori mancanti")        # 8. Salvataggio        FILE_OUT = "dataset_ml_sismico.csv"        df_ml.to_csv(FILE_OUT, index=True, index_label="Tempo")        tempo_elaborazione = time.time() - tempo_inizio        print(f"📊 === SINTESI DATASET MACHINE LEARNING ===")        print("-" * 60)        print(f"Righe totali (Ore campionate): {len(df_ml)}")        print(f"Ore con Allarme (Target=1): {df_ml['Target_Allarme'].sum()}")        print(            f"Percentuale allarmi: {df_ml['Target_Allarme'].sum() / len(df_ml) * 100:.2f}%"        )        print(f"Feature totali: {len(df_ml.columns) - 1}")        print(f"Valori mancanti: {missing_pct:.1f}%")        print("-" * 60)        print(f"✅ Dataset addestramento avanzato salvato: '{FILE_OUT}'")        print(f"⏱️ Tempo impiegato: {tempo_elaborazione:.2f}s")        # Mostra prime righe        print("📋 Anteprima dataset:")        print(df_ml.head().T)    except DataValidationError as e:        logger.error(f"❌ Validazione dati fallita: {e.message}")        for err in e.errors:            logger.error(f"   {err}")        raise    except Exception as e:        logger.error(f"❌ Errore critico in prepara_ml.py: {str(e)}", exc_info=True)        raiseif __name__ == "__main__":    main()